import java.sql.*;import com.alibaba.fastjson2.*;
public class CharsetProbe {
 public static void main(String[]a)throws Exception{JSONObject out=new JSONObject();try(Connection c=DriverManager.getConnection(a[0],"root","")){JSONArray cols=new JSONArray();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COLUMN_NAME,CHARACTER_SET_NAME,COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='anchors' AND COLUMN_NAME='props'")){while(r.next())cols.add(LittleXSql.obj("column",r.getString(1),"charset",r.getString(2),"collation",r.getString(3)));}out.put("columns",cols);try(Statement s=c.createStatement()){s.execute("CREATE TEMPORARY TABLE wb_charset_probe(props LONGTEXT CHARACTER SET utf8mb4)");}JSONArray phases=new JSONArray();for(int phase=0;phase<2;phase++){JSONObject v=new JSONObject();if(phase==1)try(Statement s=c.createStatement()){s.execute("SET NAMES utf8mb4 COLLATE utf8mb4_bin");}try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT @@character_set_client,@@character_set_connection,@@character_set_results,@@character_set_database")){r.next();v.put("session",LittleXSql.obj("client",r.getString(1),"connection",r.getString(2),"results",r.getString(3),"database",r.getString(4)));}try(PreparedStatement p=c.prepareStatement("INSERT INTO wb_charset_probe(props) VALUES(?)")){p.setString(1,"{\"archetype\":{\"content\":\"hello 🌎\"}}");p.executeUpdate();v.put("insert","PASS");}catch(SQLException e){v.put("insert","failed");v.put("error",e.toString());}phases.add(v);}out.put("phases",phases);}System.out.println(out.toJSONString());System.exit(0);}
}
